      "check_id": "CKV_AWS_290",
      "title": "Unconstrained SSM write access",
      "resource": "aws_iam_policy.privesc-ssmStartSession-policy",
      "severity": "MEDIUM",
      "explanation": "The write actions ssm:StartSession, ssm:TerminateSession, and ssm:ResumeSession are granted globally, creating a direct privilege-escalation and session-interference risk."
    }
  ],
  "patched_code": "variable "ssm_target_resource_arns" {
  description = "Exact ARNs of the managed instances and SSM session documents on which sessions may be started."
  type        = set(string)
  nullable    = false

  validation {
    condition = length(var.ssm_target_resource_arns) > 0 && alltrue([
      for resource_arn in var.ssm_target_resource_arns : can(regex("^arn:[^*]+$", resource_arn))
    ])
    error_message = "ssm_target_resource_arns must contain at least one exact ARN and must not contain wildcards."
  }
}

variable "ssm_session_name_prefix" {
  description = "Session ID prefix belonging to the principal allowed to resume, terminate, or inspect its sessions."
  type        = string
  nullable    = false

  validation {
    condition     = can(regex("^[A-Za-z0-9+=,.@_-]+$", var.ssm_session_name_prefix))
    error_message = "ssm_session_name_prefix must be non-empty and contain only valid IAM session-name characters."
  }
}

